static long solve_case_0(int64_t p) {
    long count = 0;
    int64_t pw[6][13];
    for (int k = 0; k < 6; k++) pw[k][0] = 1;
    for (int64_t k4 = 1; k4 < p; k4++) {
      for (int e = 1; e <= 12; e++) pw[4][e] = (pw[4][e-1] * k4) % p;
      for (int64_t u31 = 0; u31 < p; u31++) {
        for (int e = 1; e <= 12; e++) pw[0][e] = (pw[0][e-1] * u31) % p;
        for (int64_t u41 = 0; u41 < p; u41++) {
          for (int e = 1; e <= 12; e++) pw[1][e] = (pw[1][e-1] * u41) % p;
          for (int64_t u51 = 0; u51 < p; u51++) {
            for (int e = 1; e <= 12; e++) pw[2][e] = (pw[2][e-1] * u51) % p;
            for (int64_t W = 0; W < p; W++) {
              for (int e = 1; e <= 12; e++) pw[3][e] = (pw[3][e-1] * W) % p;
              pw[5][1] = 0;
              int64_t A = eval_poly(c0_A20, 5, pw, p);
              int64_t B = eval_poly(c0_B20, 32, pw, p);
              int64_t u50_start = 0, u50_end = p - 1;
              if (A != 0) {
                  int64_t u_sol = ((p - B) * modinv(A, p)) % p;
                  u50_start = u_sol; u50_end = u_sol;
              } else if (B != 0) { continue; }
              for (int64_t u50 = u50_start; u50 <= u50_end; u50++) {
                  for (int e = 1; e <= 12; e++) pw[5][e] = (pw[5][e-1] * u50) % p;
                  if (eval_poly(c0_eq19, 49, pw, p) != 0) continue;
                  if (eval_poly(c0_eq18, 69, pw, p) != 0) continue;
                  if (eval_poly(c0_eq17, 92, pw, p) != 0) continue;
                  if (eval_poly(c0_eq16, 131, pw, p) != 0) continue;
                  if (eval_poly(c0_eq15, 181, pw, p) != 0) continue;
                  if (eval_poly(c0_eq14, 263, pw, p) != 0) continue;
                  if (eval_poly(c0_eq13, 326, pw, p) != 0) continue;
                  if (eval_poly(c0_eq12, 432, pw, p) != 0) continue;
                  count++;
              }
            }
          }
        }
      }
    }
    return count;
}
